/**
 * Brain signature — each intelligence's avatar: a small 3D point cloud whose
 * shape is deterministic from its handle. Density follows the number of posts
 * parsed and rotation speed follows posting frequency (both real values; when
 * they're unknown we fall back to neutral defaults, never invented numbers).
 *
 * The hero's 10 landing clusters are generated by the same function, so the
 * points that fly down from the particle "i" are exactly the points each card
 * keeps drawing after the handoff.
 */
import { gaussian, hashString, rng } from "./random";

/** Max points any signature uses; the hero clusters use this many each. */
export const SIGNATURE_MAX_POINTS = 1800;
/** Fixed tilt so blobs read as 3D, not as flat discs. */
export const SIGNATURE_TILT = 0.38;

type Lobe = { k: [number, number, number]; f: number; a: number; ph: number };

function lobes(seed: number): Lobe[] {
  const r = rng(seed ^ 0x9e3779b9);
  return Array.from({ length: 4 }, () => {
    const z = r() * 2 - 1;
    const t = r() * Math.PI * 2;
    const s = Math.sqrt(1 - z * z);
    return {
      k: [s * Math.cos(t), s * Math.sin(t), z] as [number, number, number],
      f: 1.4 + r() * 2.2,
      a: 0.05 + r() * 0.14,
      ph: r() * Math.PI * 2,
    };
  });
}

const cache = new Map<string, Float32Array>();

/**
 * Unit-scale positions (max radius ≈ 1). The first n points of a larger
 * request are identical to a smaller request, so density can change without
 * the shape jumping.
 */
export function signaturePoints(handle: string, n = SIGNATURE_MAX_POINTS): Float32Array {
  let all = cache.get(handle);
  if (!all) {
    const seed = hashString(handle);
    const L = lobes(seed);
    const r = rng(seed);
    const raw = new Float32Array(SIGNATURE_MAX_POINTS * 3);
    let maxR = 0;
    for (let i = 0; i < SIGNATURE_MAX_POINTS; i++) {
      const z = r() * 2 - 1;
      const t = r() * Math.PI * 2;
      const s = Math.sqrt(1 - z * z);
      const d: [number, number, number] = [s * Math.cos(t), s * Math.sin(t), z];
      let rad = 1;
      for (const l of L) rad += l.a * Math.sin(l.f * (d[0] * l.k[0] + d[1] * l.k[1] + d[2] * l.k[2]) * Math.PI + l.ph);
      // mostly a skin, with a soft interior so it reads as a volume
      const shell = r() < 0.78 ? 1 + gaussian(r) * 0.025 : Math.cbrt(r()) * 0.92;
      rad *= shell;
      maxR = Math.max(maxR, rad);
      raw[i * 3] = d[0] * rad;
      raw[i * 3 + 1] = d[1] * rad;
      raw[i * 3 + 2] = d[2] * rad;
    }
    for (let i = 0; i < raw.length; i++) raw[i] /= maxR;
    all = raw;
    cache.set(handle, all);
  }
  return n >= SIGNATURE_MAX_POINTS ? all : all.subarray(0, n * 3);
}

/** Points to draw for a given parsed-post count. null → neutral default. */
export function signatureDensity(postsParsed: number | null): number {
  if (postsParsed == null) return 560;
  const d = 240 + 150 * Math.log10(postsParsed + 1);
  return Math.round(Math.min(SIGNATURE_MAX_POINTS * 0.62, Math.max(160, d)));
}

/** Rotation speed in rad/s for a given posting frequency. null → neutral default. */
export function signatureSpeed(postsPerDay: number | null): number {
  if (postsPerDay == null) return 0.22;
  return Math.min(0.75, 0.08 + 0.14 * Math.log2(postsPerDay + 1));
}

/** Per-handle phase so blobs don't rotate in lockstep. */
export function signaturePhase(handle: string): number {
  return (hashString(handle + ":phase") / 4294967296) * Math.PI * 2;
}

/**
 * Shared rotation state so the hero clusters and the card canvases agree on
 * each blob's angle at the handoff. Calling it twice in one frame is a no-op
 * for the second caller (dt = 0), so any renderer may advance it.
 */
const angles = new Map<string, { angle: number; t: number }>();
export function advanceSignatureAngle(handle: string, speed: number, nowSec: number): number {
  let s = angles.get(handle);
  if (!s) {
    s = { angle: signaturePhase(handle), t: nowSec };
    angles.set(handle, s);
  }
  const dt = Math.min(0.1, Math.max(0, nowSec - s.t));
  s.angle += speed * dt;
  s.t = nowSec;
  return s.angle;
}
